        public static Entry Get(string id)
        { var specialized=ApproachGrowthCatalog.Find(id);return specialized==null?entries[id]:new Entry(specialized.Node.Name,specialized.Node.Effect,"curve.cross"); }
        public static int Count => entries.Count;
        public static bool Matches(GrowthNodeDefinition node, string query)
        {
            if (string.IsNullOrWhiteSpace(query)) return true;
            query = query.Trim().Replace("쿨타임", "재사용").Replace("대기시간", "재사용");
            Entry e = Get(node.Id);
            return Contains(node.Name, query) || Contains(GrowthCurrentTitle.For(node), query) || Contains(e.Title, query) || Contains(e.Summary, query)
                || Contains(node.Section, query) || Contains(node.Effect, query) || Contains(GrowthPlayerText.Summary(node), query);
        }
        private static bool Contains(string text, string query) => text.Replace("대기시간", "재사용").IndexOf(query, StringComparison.OrdinalIgnoreCase) >= 0;
    }
